import React, { useState, useEffect } from 'react';
import * as noticeService from '../services/noticeService';
import * as categoryService from '../services/categoryService';

const AddNotice = ({ onNoticeAdded }) => {
  const [formData, setFormData] = useState({
    noticeTitle: '',
    noticeContent: '',
    noticeDate: '',
    noticeCategory: '',
    priority: 'MEDIUM',
    audienceType: 'PUBLIC',
  });

  const [categories, setCategories] = useState([]);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchCats = async () => {
      try {
        const cats = await categoryService.getAllCategories();
        setCategories(cats || []);
        if (cats && cats.length > 0 && !formData.noticeCategory) {
          setFormData((prev) => ({ ...prev, noticeCategory: cats[0].categoryName }));
        }
      } catch (e) {
        // Fallback default categories
        setCategories([
          { id: 1, categoryName: 'Academic' },
          { id: 2, categoryName: 'Examinations' },
          { id: 3, categoryName: 'Events & Fest' },
          { id: 4, categoryName: 'Sports & Activities' },
          { id: 5, categoryName: 'General Announcements' },
        ]);
        setFormData((prev) => ({ ...prev, noticeCategory: 'General Announcements' }));
      }
    };
    fetchCats();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage('');
    setError('');

    const { noticeTitle, noticeContent, noticeDate, noticeCategory } = formData;

    if (!noticeTitle || !noticeContent || !noticeDate || !noticeCategory) {
      setError('Please fill all fields.');
      return;
    }

    setLoading(true);
    try {
      const payload = {
        title: noticeTitle,
        content: noticeContent,
        categoryName: noticeCategory,
        publishDate: noticeDate ? `${noticeDate}T00:00:00` : null,
        priority: formData.priority || 'MEDIUM',
        audienceType: formData.audienceType || 'PUBLIC',
      };

      await noticeService.addNotice(payload);
      setMessage('Notice added successfully!');
      setFormData({
        noticeTitle: '',
        noticeContent: '',
        noticeDate: '',
        noticeCategory: categories.length > 0 ? categories[0].categoryName : '',
        priority: 'MEDIUM',
        audienceType: 'PUBLIC',
      });

      if (onNoticeAdded) {
        onNoticeAdded();
      }
    } catch (err) {
      setError('Failed to add notice.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="card" style={{ maxWidth: '700px', margin: '0 auto' }}>
      <h2 style={{ marginBottom: '1.25rem' }}>Create New Notice</h2>

      {message && <div className="alert alert-success">{message}</div>}
      {error && <div className="alert alert-danger">{error}</div>}

      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label className="form-label" htmlFor="noticeTitle">
            Notice Title
          </label>
          <input
            id="noticeTitle"
            type="text"
            name="noticeTitle"
            className="form-control"
            placeholder="Enter a descriptive title..."
            value={formData.noticeTitle}
            onChange={handleChange}
          />
        </div>

        <div className="form-group">
          <label className="form-label" htmlFor="noticeCategory">
            Category
          </label>
          <select
            id="noticeCategory"
            name="noticeCategory"
            className="form-control"
            value={formData.noticeCategory}
            onChange={handleChange}
          >
            <option value="">Select Category</option>
            {categories.map((cat) => (
              <option key={cat.id || cat.categoryName} value={cat.categoryName}>
                {cat.categoryName}
              </option>
            ))}
          </select>
        </div>

        <div className="grid grid-cols-2">
          <div className="form-group">
            <label className="form-label" htmlFor="noticeDate">
              Publish Date
            </label>
            <input
              id="noticeDate"
              type="date"
              name="noticeDate"
              className="form-control"
              value={formData.noticeDate}
              onChange={handleChange}
            />
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="priority">
              Priority
            </label>
            <select
              id="priority"
              name="priority"
              className="form-control"
              value={formData.priority}
              onChange={handleChange}
            >
              <option value="LOW">Low</option>
              <option value="MEDIUM">Medium</option>
              <option value="HIGH">High</option>
              <option value="URGENT">Urgent</option>
            </select>
          </div>
        </div>

        <div className="form-group">
          <label className="form-label" htmlFor="noticeContent">
            Notice Content
          </label>
          <textarea
            id="noticeContent"
            name="noticeContent"
            className="form-control"
            rows="6"
            placeholder="Write full notice details here..."
            value={formData.noticeContent}
            onChange={handleChange}
          />
        </div>

        <div style={{ marginTop: '1.5rem', display: 'flex', justifyContent: 'flex-end' }}>
          <button type="submit" className="btn btn-primary" disabled={loading}>
            {loading ? 'Adding...' : 'Add Notice'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default AddNotice;
